/**
 * Sanitize a question so that followUp is strictly English and followUpZh is clean Chinese.
 * Removes all [追問中文]:, 追問：, and brackets.
 */
export function sanitizeQuestion(q: BenchQuestion): boolean {
  let changed = false;
  const known = OFFICIAL_FOLLOWUPS[q.id];
  if (known) {
    if (q.followUp !== known.en) { q.followUp = known.en; changed = true; }
    if (q.followUpZh !== known.zh) { q.followUpZh = known.zh; changed = true; }
    return changed;
  }

  // Check if followUp contains Chinese or tags
  if (q.followUp && (/[\u4e00-\u9fa5]/.test(q.followUp) || q.followUp.includes('[追問中文]'))) {
    const cleanZh = q.followUp.replace(/^\[追問中文\]:?\s*/, '').replace(/^追問[：:]\s*/, '').trim();
    if (!q.followUpZh) {
      q.followUpZh = cleanZh;
    }
    // If followUp has no English sentence, provide a standard moot court challenge
    q.followUp = 'Counsel, how do you reconcile that proposition with the established facts and the express requirements of the Rome Statute?';
    changed = true;
  } else if (q.followUp) {
    // Ensure clean English formatting
    const cleaned = q.followUp.replace(/^\[[^\]]+\]\s*/, '').trim();
    if (cleaned !== q.followUp) {
      q.followUp = cleaned;
      changed = true;
    }
  }

  if (q.followUpZh && q.followUpZh.includes('[追問中文]')) {
    q.followUpZh = q.followUpZh.replace(/^\[追問中文\]:?\s*/, '').replace(/^追問[：:]\s*/, '').trim();
    changed = true;
  }

  return changed;
}

export function sanitizeDebateData(data: DebateData): boolean {
  if (!data) return false;
  let changed = false;
  if (Array.isArray(data.prosecutionQuestions)) {
    for (const q of data.prosecutionQuestions) {
      if (sanitizeQuestion(q)) changed = true;
    }
  }
  if (Array.isArray(data.defenseQuestions)) {
    for (const q of data.defenseQuestions) {
      if (sanitizeQuestion(q)) changed = true;
    }
  }
  return changed;
}
